import { useState, type HTMLAttributes } from "react";
import { Badge } from "../ui/Badge";
import { CodeBlock } from "../ui/CodeBlock";
import { ScrollArea } from "../ui/ScrollArea";
import { mergeClasses } from "../ui/classes";
import { CompositionRoot } from "./_CompositionRoot";
import type { CompositionSurfaceProps } from "./composition";

export interface WorkspaceFile {
  id: string;
  path: string;
  added: number;
  removed: number;
}

/**
 * A file list against the diff it selects, at a fixed split.
 *
 * It was resizable, and that was the wrong control here: the two panes have
 * settled proportions — a path list is narrow, a diff is wide — so a handle only
 * invited the reader to make it worse. Resizable belongs where the trade is
 * genuinely theirs, which is the before-and-after comparison.
 */
const defaultFiles: readonly WorkspaceFile[] = [
  { id: "config", path: "deploy/atlas.config.ts", added: 18, removed: 4 },
  { id: "runner", path: "deploy/runner.ts", added: 7, removed: 7 },
  { id: "environments", path: "deploy/environments.ts", added: 2, removed: 0 },
  { id: "health", path: "deploy/health-check.ts", added: 24, removed: 3 },
  { id: "rollback", path: "deploy/rollback.ts", added: 12, removed: 9 },
  { id: "regions", path: "config/regions.json", added: 3, removed: 1 },
  { id: "workflow", path: ".github/workflows/deploy.yml", added: 6, removed: 6 },
  { id: "tests", path: "tests/rollout.test.ts", added: 41, removed: 0 },
  { id: "readme", path: "README.md", added: 11, removed: 1 },
];

const defaultSource = `export const atlas = {
  regions: ["iad1", "fra1", "gru1"],
  strategy: "rolling",
  healthCheck: "/internal/ready",
  healthChecksBeforePromotion: 2,
  holdAtPercent: 10,
  rollbackAfter: 90,
  notifyOnFailure: ["#atlas-deploys"],
};`;

export interface SplitWorkspaceCardProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title?: string;
  description?: string;
  files?: readonly WorkspaceFile[];
  source?: string;
}

export function SplitWorkspaceCard({
  title = "Review changes",
  description = "Nine files changed in this pull request.",
  files = defaultFiles,
  source = defaultSource,
  headingLevel,
  shadow,
  theme,
  "data-balsa": _dataBalsa,
  ...domProps
}: SplitWorkspaceCardProps) {
  void _dataBalsa;
  const [active, setActive] = useState("config");

  return (
    <CompositionRoot
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow}
      theme={theme}
      data-composition="split-workspace"
      action={<Badge variant="soft">+124 −31</Badge>}
    >
      <div className="grid min-h-0 flex-1 grid-rows-1 sm:grid-cols-[minmax(0,14rem)_minmax(0,1fr)]">
        <ScrollArea label="Changed files" className="min-h-0 rounded-r-none border-r-0">
          <ul className="grid gap-balsa-3xs p-balsa-xs" role="list">
            {files.map((file) => (
              <li key={file.id}>
                <button
                  type="button"
                  aria-current={active === file.id ? "true" : undefined}
                  className={mergeClasses(
                    "flex w-full items-center justify-between gap-balsa-xs rounded-balsa-control px-balsa-sm py-balsa-xs text-left focus-visible:outline focus-visible:outline-2 focus-visible:outline-balsa-focus-ring",
                    active === file.id ? "bg-balsa-muted font-medium" : "hover:bg-balsa-muted",
                  )}
                  onClick={() => setActive(file.id)}
                >
                  <span className="min-w-0 truncate text-xs">{file.path}</span>
                  <span className="shrink-0 text-xs tabular-nums text-balsa-muted-foreground">
                    +{file.added} −{file.removed}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </ScrollArea>
        <CodeBlock
          code={source}
          language="ts"
          className="min-h-0 rounded-l-none border-l-0 [&>pre]:h-full [&_pre]:min-h-full"
        />
      </div>
    </CompositionRoot>
  );
}

import { type HTMLAttributes, type ReactNode } from "react";
import { mergeClasses } from "../ui/classes";
import { ApplicationCard } from "./ApplicationCard";
import type { CompositionSurfaceProps } from "./composition";

export interface CompositionRootProps extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "color">, CompositionSurfaceProps {
  "data-balsa"?: string;
  title: string;
  description?: string;
  action?: ReactNode;
  footer?: ReactNode;
  children?: ReactNode;
}

export function CompositionRoot({
  title,
  description,
  headingLevel = 2,
  shadow = "auto",
  theme,
  action,
  footer,
  children,
  className,
  "data-balsa": _dataBalsa,
  ...domProps
}: CompositionRootProps) {
  void _dataBalsa;

  return (
    <ApplicationCard
      {...domProps}
      title={title}
      description={description}
      headingLevel={headingLevel}
      shadow={shadow ?? "auto"}
      theme={theme}
      action={action}
      footer={footer}
      className={mergeClasses("min-w-0", className)}
    >
      {children}
    </ApplicationCard>
  );
}

import type { Shadow, ThemeInput } from "../ui/theme";

export interface CompositionSurfaceProps {
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  shadow?: Shadow;
  theme?: ThemeInput;
}

export interface CompositionOption {
  label: string;
  value: string;
  description?: string;
}

export interface CompositionMetric {
  label: string;
  value: string;
  detail?: string;
}

export type CompositionPaletteColor = "primary" | "secondary" | "accent";
